const headers = $json.headers || {};
const expectedSecret = $env.WEBHOOK_SECRET_KEY || '';
const incomingSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';

const isAuthorized = Boolean(expectedSecret && incomingSecret === expectedSecret);

return {
  is_authorized: isAuthorized,
  headers: headers,
  body: $json.body || {}
};

const crypto = require('crypto');
const body = $json.body || {};
const errors = [];

const name = typeof body.name === 'string' ? body.name.trim() : '';
const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : '';
const message = typeof body.message === 'string' ? body.message.trim() : '';

if (!name || name.length < 2) {
  errors.push("Field 'name' is required and must have at least 2 characters.");
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!email || !emailRegex.test(email)) {
  errors.push("Field 'email' is required and must be a valid email address.");
}

if (!message || message.length < 5) {
  errors.push("Field 'message' is required and must have at least 5 characters.");
}

if (errors.length > 0) {
  return {
    is_valid: false,
    errors: errors,
    body: body
  };
}

// Compute idempotency SHA-256 hash based on normalized email and message
const idempotencyHash = crypto.createHash('sha256').update(`${email}|${message}`).digest('hex');

// Fast rule-based spam keywords filter
const spamKeywords = [
  /\bviagra\b/i,
  /\bcasino\b/i,
  /\bcrypto\s*doubler\b/i,
  /\bguaranteed\s*seo\b/i,
  /\bbacklinks?\s*package\b/i,
  /\bmake\s*\$?\d+\s*(per|a)\s*day\b/i,
  /\btelegram\s*investment\b/i,
  /\bwhatsapp\s*loan\b/i,
  /\bfree\s*money\b/i,
  /\bclaim\s*your\s*prize\b/i
];

const isSpam = spamKeywords.some(pattern => pattern.test(message) || pattern.test(name));

return {
  is_valid: true,
  is_spam: isSpam,
  name: name,
  email: email,
  message: message,
  idempotency_hash: idempotencyHash,
  raw_payload: JSON.stringify(body)
};

