const prevLead = $('Validate Input & Rule Filter').first().json;
const llmResponse = $json;

let parsed = null;
let fallbackReason = null;

try {
  if (llmResponse.error) {
    fallbackReason = 'API error: ' + (llmResponse.error.message || JSON.stringify(llmResponse.error));
  } else {
    const parts = llmResponse.candidates?.[0]?.content?.parts || [];
    let text = null;
    for (let i = parts.length - 1; i >= 0; i--) {
      if (parts[i].text && parts[i].text.includes('{') && !parts[i].thought) {
        text = parts[i].text;
        break;
      }
    }
    if (!text && parts.length > 0) {
      text = parts[parts.length - 1].text;
    }

    if (text) {
      let cleanText = text.trim();
      const jsonMatch = cleanText.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
      if (jsonMatch) {
        cleanText = jsonMatch[1];
      } else {
        const firstBrace = cleanText.indexOf('{');
        const lastBrace = cleanText.lastIndexOf('}');
        if (firstBrace !== -1 && lastBrace !== -1) {
          cleanText = cleanText.substring(firstBrace, lastBrace + 1);
        }
      }
      parsed = JSON.parse(cleanText);
    } else {
      fallbackReason = 'Empty response or missing candidate parts';
    }
  }
} catch (e) {
  fallbackReason = 'JSON parse error: ' + e.message;
}

// Validate strict fields
const validCategories = ['sales', 'support', 'spam', 'other'];
const validUrgencies = ['low', 'medium', 'high'];

let category = 'other';
let urgency = 'medium';
let summary = '';
let suggestedReply = '';
let needsHumanReview = false;

const parsedCat = parsed && typeof parsed.category === 'string' ? parsed.category.toLowerCase().trim() : '';
const parsedUrg = parsed && typeof parsed.urgency === 'string' ? parsed.urgency.toLowerCase().trim() : '';

if (parsed && validCategories.includes(parsedCat) && validUrgencies.includes(parsedUrg)) {
  category = parsedCat;
  urgency = parsedUrg;
  summary = typeof parsed.summary === 'string' ? parsed.summary.trim() : 'Inquiry received.';
  suggestedReply = typeof parsed.suggested_reply === 'string' ? parsed.suggested_reply.trim() : 'Thank you for reaching out.';
  needsHumanReview = typeof parsed.needs_human_review === 'boolean' ? parsed.needs_human_review : (category === 'support' && urgency === 'high');
} else {
  // Fallback as specified: category 'other' + flag needs_human_review
  category = 'other';
  urgency = 'medium';
  summary = fallbackReason ? `Automated classification failed (${fallbackReason}).` : 'Malformed classification schema.';
  suggestedReply = 'Thank you for contacting us. We have received your request and our team will review it shortly.';
  needsHumanReview = true;
}

return {
  name: prevLead.name,
  email: prevLead.email,
  message: prevLead.message,
  idempotency_hash: prevLead.idempotency_hash,
  raw_payload: prevLead.raw_payload,
  category: category,
  urgency: urgency,
  summary: summary,
  suggested_reply: suggestedReply,
  needs_human_review: needsHumanReview,
  source: fallbackReason ? 'llm_fallback' : 'gemini_llm'
};

const insertResult = $json;
const isNewLead = Boolean(insertResult && insertResult.id);

let prevData = {};
try {
  if ($('Parse & Validate LLM JSON').isExecuted) {
    prevData = $('Parse & Validate LLM JSON').first().json;
  } else if ($('Handle Spam Shortcut').isExecuted) {
    prevData = $('Handle Spam Shortcut').first().json;
  } else {
    prevData = $('Validate Input & Rule Filter').first().json;
  }
} catch (e) {
  try {
    prevData = $('Handle Spam Shortcut').first().json;
  } catch (err) {
    prevData = $('Validate Input & Rule Filter').first().json;
  }
}

return {
  ...prevData,
  lead_id: insertResult.id || null,
  is_duplicate: !isNewLead
};

